CREATE TABLE IF NOT EXISTS category (id BIGINT AUTO_INCREMENT PRIMARY KEY, parent_id BIGINT NULL, name VARCHAR(80) NOT NULL, sort_order INT NOT NULL DEFAULT 0, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS shop (id BIGINT AUTO_INCREMENT PRIMARY KEY, seller_id BIGINT NOT NULL UNIQUE, merchant_application_id VARCHAR(80) UNIQUE, name VARCHAR(80) NOT NULL, announcement VARCHAR(500) NOT NULL DEFAULT '', status VARCHAR(20) NOT NULL, decoration_template VARCHAR(20) NOT NULL DEFAULT 'CLASSIC', decoration_json TEXT NOT NULL, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS product (id BIGINT AUTO_INCREMENT PRIMARY KEY, seller_id BIGINT NOT NULL, shop_id BIGINT NOT NULL, category_id BIGINT NOT NULL, name VARCHAR(120) NOT NULL, description VARCHAR(2000) NOT NULL DEFAULT '', price DECIMAL(12,2) NOT NULL, stock INT NOT NULL, reserved_stock INT NOT NULL DEFAULT 0, status VARCHAR(32) NOT NULL, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_product_shop FOREIGN KEY(shop_id) REFERENCES shop(id));
CREATE TABLE IF NOT EXISTS product_risk_audit (id BIGINT AUTO_INCREMENT PRIMARY KEY, product_id BIGINT NOT NULL, snapshot_name VARCHAR(120) NOT NULL, snapshot_description TEXT NOT NULL, risk_level VARCHAR(20) NOT NULL, rule_hits VARCHAR(500) NOT NULL DEFAULT '', status VARCHAR(20) NOT NULL, decision_reason VARCHAR(500) NOT NULL DEFAULT '', admin_id BIGINT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS browse_history (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, product_id BIGINT NOT NULL, product_type VARCHAR(20) NOT NULL, browsed_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS user_search_history (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, keyword VARCHAR(64) NOT NULL, searched_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS search_keyword_stat (keyword VARCHAR(64) PRIMARY KEY, search_count INT NOT NULL, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS inventory_reservation (id BIGINT AUTO_INCREMENT PRIMARY KEY, idempotency_key VARCHAR(128) NOT NULL UNIQUE, order_id VARCHAR(80) NOT NULL, status VARCHAR(20) NOT NULL, expires_at TIMESTAMP NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS inventory_reservation_item (reservation_id BIGINT NOT NULL, product_id BIGINT NOT NULL, quantity INT NOT NULL, PRIMARY KEY(reservation_id, product_id), CONSTRAINT fk_reservation_item FOREIGN KEY(reservation_id) REFERENCES inventory_reservation(id));
CREATE TABLE IF NOT EXISTS idempotency_record (scope VARCHAR(64) NOT NULL, idempotency_key VARCHAR(128) NOT NULL, resource_id VARCHAR(80) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(scope,idempotency_key));
CREATE TABLE IF NOT EXISTS outbox_event (id BIGINT AUTO_INCREMENT PRIMARY KEY, event_id VARCHAR(80) NOT NULL UNIQUE, aggregate_type VARCHAR(40) NOT NULL, aggregate_id VARCHAR(80) NOT NULL, event_type VARCHAR(80) NOT NULL, payload TEXT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'PENDING', attempts INT NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_product_public ON product(status, category_id, updated_at);
CREATE INDEX idx_browse_user ON browse_history(user_id, browsed_at);
CREATE INDEX idx_search_user ON user_search_history(user_id, searched_at);
